class Solution {
public:
    int minOperations(string initial, string target) {
        int m = initial.size(), n = target.size();
        vector<int> dp(n + 1, 0);
        int max_len = 0;
        for (int i = 1; i <= m; ++i) {
            vector<int> nxt_dp(n + 1, 0);
            for (int j = 1; j <= n; ++j) {
                if (initial[i - 1] == target[j - 1]) {
                    nxt_dp[j] = dp[j - 1] + 1;
                    max_len = max(max_len, nxt_dp[j]);
                }
            }
            dp = nxt_dp;
        }
        return m + n - 2 * max_len;
    }
};

class Solution {
    public int minOperations(String initial, String target) {
        int m = initial.length(), n = target.length();
        int[] dp = new int[n + 1];
        int maxLen = 0;
        for (int i = 1; i <= m; i++) {
            int[] nxtDp = new int[n + 1];
            for (int j = 1; j <= n; j++) {
                if (initial.charAt(i - 1) == target.charAt(j - 1)) {
                    nxtDp[j] = dp[j - 1] + 1;
                    maxLen = Math.max(maxLen, nxtDp[j]);
                }
            }
            dp = nxtDp;
        }
        return m + n - 2 * maxLen;
    }
}

var minOperations = function(initial, target) {
    const m = initial.length, n = target.length;
    let dp = new Array(n + 1).fill(0);
    let maxLen = 0;
    for (let i = 1; i <= m; i++) {
        const nxtDp = new Array(n + 1).fill(0);
        for (let j = 1; j <= n; j++) {
            if (initial[i - 1] === target[j - 1]) {
                nxtDp[j] = dp[j - 1] + 1;
                maxLen = Math.max(maxLen, nxtDp[j]);
            }
        }
        dp = nxtDp;
    }
    return m + n - 2 * maxLen;
